function eligibleGroupCandidates(selected, blocklists, ctx, rows = loadCandidatePool()) {
  rebuildCanonicalCleanVariantSignatures(rows, ctx.acquisitionVariantArtists || null);
  const stats = newRejectionStats(rows.length);
  const eligible = [];
  const artistFeedback = ctx.retentionFeedback?.artistStats || feedbackArtistStats();
  const seenIds = new Set();

  for (const row of rows) {
    const track = row?.track;
    if (!track?.id || !track?.uri || seenIds.has(track.id)) {
      stats.invalid++;
      continue;
    }
    seenIds.add(track.id);

    if (trackHasArtistExclusion(track)) {
      stats.artistIdExcluded++;
      continue;
    }
    if ((ctx.retentionSnapshot ? Number(ctx.retentionSnapshot.feedback[trackSignature(track)]?.value || 0) : trackFeedbackValue(track)) < 0) {
      stats.feedbackTrack++;
      continue;
    }
    if (looksLikeUnwantedVariant(track, ctx.acquisitionVariantArtists || null)) {
      stats.unwantedVariant++;
      continue;
    }

    const artistIds = (track.artists || []).map(a => a?.id || "").filter(Boolean);
    const artistNames = (track.artists || []).map(a => normalizeArtistName(a?.name || "")).filter(Boolean);

    if (artistNames.some(name => blocklists.explicitBlockedNames.has(name))) {
      stats.explicitBlockedArtist++;
      continue;
    }
    if (artistNames.some(name => blocklists.feedbackBlockedNames.has(name))) {
      stats.feedbackBlockedArtist++;
      continue;
    }
    if (hasStrongNegativeArtistFeedback(track, artistFeedback)) {
      stats.strongNegativeArtistFeedback++;
      continue;
    }
    if (
      artistIds.some(id => blocklists.blockedArtists.has(id)) ||
      artistNames.some(name => blocklists.historyBlockedNames.has(name))
    ) {
      stats.artistCooldown++;
      continue;
    }

    const signature = trackSignature(track);
    const duplicateSignatures = trackDuplicateSignatures(track);
    if (
      blocklists.blockedTracks.has(track.id) ||
      (signature && blocklists.blockedTrackSignatures.has(signature)) ||
      duplicateSignatures.some(key => blocklists.blockedTrackSignatures.has(key))
    ) {
      stats.recentTrack++;
      continue;
    }

    const staticInfo = groupCandidateStatic(track, ctx);
    const strongTasteDiscovery =
      Number(discoveryLevel.value || 0) > 0 &&
      staticInfo.maxScore >= 72 &&
      (staticInfo.likedByAny || staticInfo.seedByAny);

    if (!recognizabilityPass(track, ctx.retentionSnapshot) && !strongTasteDiscovery) {
      stats.recognizability++;
      continue;
    }

    if (staticInfo.groupBase < 34 || staticInfo.maxScore < 45) {
      stats.lowGroupFit++;
      continue;
    }

    eligible.push(staticInfo);
    stats.eligible++;
  }

  return { eligible, stats };
}

sources.selectGroupPlaylist:
function selectGroupPlaylist(eligible, total, ctx, stats) {
  const requestedDiscoveryQuota = discoveryQuotaForTotal(total);
  const state = {
    selected: [],
    selectedIds: new Set(),
    selectedSignatures: new Set(),
    artistCounts: new Map(),
    userSums: new Map((ctx.selected || []).map(profile => [profile.id, 0])),
    aspectCounts: new Map(),
    discoveryCount: 0,
    polishCount: 0,
    details: new Map()
  };

  // Recheck at selection entry: cached/static candidates and direct callers
  // must obey the same per-artist rule in every normal/fallback branch.
  const artistFeedback = feedbackArtistStats();
  const remaining = eligible.filter(item => {
    if (trackHasArtistExclusion(item.track)) { stats.artistIdExcluded = (stats.artistIdExcluded || 0) + 1; return false; }
    if (!hasStrongNegativeArtistFeedback(item.track, artistFeedback)) return true;
    stats.strongNegativeArtistFeedback = (stats.strongNegativeArtistFeedback || 0) + 1;
    return false;
  });

  while (state.selected.length < total && remaining.length) {
    let choices = [];

    for (let i = 0; i < remaining.length; i++) {
      const item = remaining[i];
      const track = item.track;
      const signature = trackSignature(track);
      const duplicateSignatures = trackDuplicateSignatures(track);
      const artists = [...trackArtistKeys(track)];

      if (
        state.selectedIds.has(track.id) ||
        (signature && state.selectedSignatures.has(signature)) ||
        duplicateSignatures.some(key => state.selectedSignatures.has(key))
      ) {
        stats.duplicateDuringSelection++;
        continue;
      }
      if (artists.some(key => (state.artistCounts.get(key) || 0) >= 2)) {
        stats.artistLimitDuringSelection++;
        continue;
      }

      const previous = state.selected[state.selected.length - 1];
      if (previous && tracksShareArtist(previous, track)) continue;

      const projectedLength = state.selected.length + 1;
      const projectedQuota = discoveryQuotaForTotal(projectedLength);
      if (item.features.discovery && state.discoveryCount + 1 > projectedQuota.max) continue;

      choices.push({ index: i, item, dynamic: dynamicCandidateScore(item, state, ctx) });
    }

    if (!choices.length) {
      for (let i = 0; i < remaining.length; i++) {
        const item = remaining[i];
        const track = item.track;
        const signature = trackSignature(track);
        const duplicateSignatures = trackDuplicateSignatures(track);
        const artists = [...trackArtistKeys(track)];

        if (
          state.selectedIds.has(track.id) ||
          (signature && state.selectedSignatures.has(signature)) ||
          duplicateSignatures.some(key => state.selectedSignatures.has(key)) ||
          artists.some(key => (state.artistCounts.get(key) || 0) >= 2)
        ) continue;
        const projectedLength = state.selected.length + 1;
        const projectedQuota = discoveryQuotaForTotal(projectedLength);
        if (item.features.discovery && state.discoveryCount + 1 > projectedQuota.max) continue;

        choices.push({ index: i, item, dynamic: dynamicCandidateScore(item, state, ctx) });
      }
    }

    // MMR ma zmieniać kolejność preferencji, a nie kończyć playlistę tylko dlatego,
    // że po wielu podobnych utworach dynamiczny wynik został chwilowo mocno obniżony.
    // Normalna ścieżka zachowuje dotychczasowy próg >=44 i dynamiczną quota discovery.
    let qualityChoices = choices.filter(choice => choice.item.groupBase >= GROUP_HARD_MIN_BASE_SCORE);
    let usedFallback = false;

    if (!qualityChoices.length) {
      // v40: końcowy fallback nie może zakleszczać się przez quota liczoną względem
      // aktualnie krótkiej playlisty. Używamy górnego limitu discovery dla docelowej
      // długości, nadal zachowując limit 2 utworów wykonawcy, deduplikację i min 35
      // dla każdej obecnej osoby. Nie wymagamy już, by któryś profil miał >=65.
      const fallbackChoices = [];
      const targetDiscoveryMax = requestedDiscoveryQuota.max;

      const collectFallbackChoices = (respectAdjacentArtist) => {
        fallbackChoices.length = 0;
        for (let i = 0; i < remaining.length; i++) {
          const item = remaining[i];
          const track = item.track;
          const signature = trackSignature(track);
          const duplicateSignatures = trackDuplicateSignatures(track);
          const artists = [...trackArtistKeys(track)];

          if (
            state.selectedIds.has(track.id) ||
            (signature && state.selectedSignatures.has(signature)) ||
            duplicateSignatures.some(key => state.selectedSignatures.has(key)) ||
            artists.some(key => (state.artistCounts.get(key) || 0) >= 2)
          ) continue;

          const previous = state.selected[state.selected.length - 1];
          if (respectAdjacentArtist && previous && tracksShareArtist(previous, track)) continue;
          if (item.features.discovery && state.discoveryCount + 1 > targetDiscoveryMax) continue;
          if (item.groupBase < GROUP_FALLBACK_MIN_BASE_SCORE) continue;
          if (item.minScore < GROUP_FALLBACK_MIN_USER_SCORE) continue;
          // Preserve the existing aggregate feedback guard in fallback.
          // The per-artist exclusion already applies to every branch above.
          if (item.features.feedback <= GROUP_FALLBACK_MIN_FEEDBACK) continue;

          fallbackChoices.push({ index: i, item, dynamic: dynamicCandidateScore(item, state, ctx) });
        }
      };

      collectFallbackChoices(true);
      if (!fallbackChoices.length) collectFallbackChoices(false);
      if (fallbackChoices.length) {
        qualityChoices = fallbackChoices;
        usedFallback = true;
      }
    }

    if (!qualityChoices.length) {
      stats.lowFinalScoreStop = remaining.length;
      stats.selectionStopDiagnostics = analyzeSelectionStop(remaining, state, total);
      break;
    }
    qualityChoices.sort((a, b) => b.dynamic.final - a.dynamic.final);
    const picked = qualityChoices[0];
    const track = picked.item.track;
    if (usedFallback) stats.fallbackSelections++;

    state.selected.push(track);
    state.selectedIds.add(track.id);
    const signature = trackSignature(track);
    if (signature) state.selectedSignatures.add(signature);
    for (const duplicateSignature of trackDuplicateSignatures(track)) {
      state.selectedSignatures.add(duplicateSignature);
    }
    for (const key of trackArtistKeys(track)) {
      state.artistCounts.set(key, (state.artistCounts.get(key) || 0) + 1);
    }
    for (const profile of ctx.selected || []) {
      const score = picked.item.byUser[profile.id]?.score || 0;
      state.userSums.set(profile.id, (state.userSums.get(profile.id) || 0) + score);
    }
    for (const aspect of supportedAspectsForCandidate(picked.item, ctx)) {
      state.aspectCounts.set(aspect, (state.aspectCounts.get(aspect) || 0) + 1);
    }
    if (picked.item.features.discovery) state.discoveryCount++;
    if (picked.item.features.isPolish) state.polishCount++;

    state.details.set(track.id, {
      byUser: Object.fromEntries(
        (ctx.selected || []).map(profile => [
          profile.id,
          picked.item.byUser[profile.id]?.score || 0
        ])
      ),
      groupBase: picked.item.groupBase,
      leastMiseryPenalty: picked.item.leastMiseryPenalty,
      fairness: picked.dynamic.fairness,
      xquad: picked.dynamic.xquad,
      polishBoost: picked.dynamic.polish,
      isPolish: picked.item.features.isPolish,
      fallback: usedFallback,
      mmr: picked.dynamic.mmr,
      discovery: picked.item.features.discovery,
      final: picked.dynamic.final
    });

    remaining.splice(picked.index, 1);
  }

  const satisfaction = {};
  for (const profile of ctx.selected || []) {
    const scores = state.selected.map(track =>
      groupCandidateStatic(track, ctx).byUser[profile.id]?.score || 0
    );
    satisfaction[profile.id] = {
      average: scores.length ? scores.reduce((a, b) => a + b, 0) / scores.length : 0,
      strong: scores.filter(score => score >= 65).length,
      weak: scores.filter(score => score < 35).length
    };
  }

  return {
    tracks: state.selected,
    details: state.details,
    satisfaction,
    discoveryCount: state.discoveryCount,
    polishCount: state.polishCount,
    discoveryQuota: discoveryQuotaForTotal(state.selected.length),
    requestedDiscoveryQuota,
    aspectCounts: state.aspectCounts,
    rejectionStats: stats
  };
}
